<script lang="ts">
 import {onMount,getContext} from 'svelte';import {locale,t} from '$lib/i18n';import type {components} from '$lib/api/api';
 let user:()=>components['schemas']['UserRead']=getContext('user');let requests=$state<any[]>([]),error=$state(''),busy=$state(false);
 async function load(){try{const r=await fetch('/api/v1/tv/episodes/requests');if(!r.ok)throw Error(t($locale,'Requests could not be loaded.'));requests=await r.json();}catch(e){error=(e as Error).message;}}
 onMount(load);
 async function update(id:string,method:string,authorized?:boolean){busy=true;error='';try{const r=await fetch('/api/v1/tv/episodes/requests/'+id,{method,headers:{'Content-Type':'application/json'},body:method==='PUT'?JSON.stringify({authorized}):undefined});if(!r.ok){const d=await r.json();throw Error(d.detail??t($locale,'Request failed'));}await load();}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<section class="space-y-3 rounded-xl border p-4"><h2 class="text-xl font-semibold">{t($locale,'Episode requests')}</h2>{#if error}<p role="alert" class="text-destructive">{t($locale,error)}</p>{/if}
{#each requests as request}<article class="flex flex-wrap items-center justify-between gap-3 rounded-lg border p-3"><div><h3 class="font-medium">{request.show_name} · S{String(request.season_number).padStart(2,'0')}E{String(request.episode_number).padStart(2,'0')}</h3><p class="text-sm text-muted-foreground">{request.episode_title} · {t($locale,request.authorized?'Approved':'Pending approval')}</p></div><div class="flex gap-2">{#if user().is_superuser}<button class="rounded-lg border px-3 py-2 disabled:opacity-50" disabled={busy} onclick={()=>update(request.id,'PUT',!request.authorized)}>{t($locale,request.authorized?'Revoke approval':'Approve')}</button>{/if}<button class="rounded-lg border px-3 py-2 disabled:opacity-50" disabled={busy} onclick={()=>{if(confirm(t($locale,'Delete request?')))update(request.id,'DELETE');}}>{t($locale,'Delete request')}</button></div></article>{:else}<p class="text-sm text-muted-foreground">{t($locale,'No episode requests.')}</p>{/each}</section>
